TREE = ("# Шабуыл ағашы: OR - кез келген баланың сәттілігі жеткілікті, AND - бәрі керек.\n"
        "# Жапырақтағы сан - шабуылдаушы осы қадамды жүзеге асыру ықтималдығы (бағалау).\n"
        "tree = ('OR', [\n"
        "    ('AND', [('leaf', 'құпиясөзді фишингпен алу', 0.10), ('leaf', '2FA жоқ', 0.40)]),\n"
        "    ('leaf', 'SQL инъекциясы', 0.05),\n"
        "    ('AND', [('leaf', 'ескі сессия токені ағып кетті', 0.08), ('leaf', 'токеннің мерзімі шексіз', 0.60)]),\n"
        "])\n\n"
        "def p(node):\n"
        "    kind = node[0]\n"
        "    if kind == 'leaf':\n"
        "        return node[2]\n"
        "    probs = [p(ch) for ch in node[1]]\n"
        "    if kind == 'AND':\n"
        "        out = 1.0\n"
        "        for x in probs:\n"
        "            out *= x\n"
        "        return out\n"
        "    fail = 1.0\n"
        "    for x in probs:\n"
        "        fail *= 1 - x\n"
        "    return 1 - fail\n\n"
        "print(f'шабуылдың сәттілік ықтималдығы: {p(tree):.4f}')\n"
        "for name, fix in [('2FA қосу', ('leaf', '2FA жоқ', 0.02)), ('токен мерзімін 1 сағ ету', ('leaf', 'токеннің мерзімі шексіз', 0.05))]:\n"
        "    def patch(n):\n"
        "        if n[0] == 'leaf':\n"
        "            return fix if n[1] == fix[1] else n\n"
        "        return (n[0], [patch(c) for c in n[1]])\n"
        "    print(f'{name:26} -> {p(patch(tree)):.4f}')")

