TOKEN = ("import base64, hashlib, hmac, json\n\n"
         "SECRET = b'server-side-secret-key-32-bytes!'    # тек серверде, ешқашан клиентке\n\n"
         "def b64(data):\n"
         "    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()\n\n"
         "def unb64(s):\n"
         "    return base64.urlsafe_b64decode(s + '=' * (-len(s) % 4))\n\n"
         "def sign(payload):\n"
         "    body = b64(json.dumps(payload, sort_keys=True).encode())\n"
         "    tag = b64(hmac.new(SECRET, body.encode(), hashlib.sha256).digest())\n"
         "    return body + '.' + tag\n\n"
         "def verify(token, now):\n"
         "    try:\n"
         "        body, tag = token.split('.')\n"
         "    except ValueError:\n"
         "        return None, 'пішімі қате'\n"
         "    good = b64(hmac.new(SECRET, body.encode(), hashlib.sha256).digest())\n"
         "    if not hmac.compare_digest(good, tag):\n"
         "        return None, 'қолтаңба жарамсыз'\n"
         "    payload = json.loads(unb64(body))\n"
         "    if payload['exp'] <= now:\n"
         "        return None, 'мерзімі өтті'\n"
         "    return payload, 'ok'\n\n"
         "t = sign({'user': 'aigul', 'role': 'student', 'exp': 1000})\n"
         "print('токен:', t[:32] + '...')\n"
         "print(verify(t, now=900))\n"
         "print(verify(t, now=1001))\n"
         "# шабуылдаушы рөлді өзгертті, бірақ құпия кілтті білмейді\n"
         "forged_body = b64(json.dumps({'exp': 1000, 'role': 'admin', 'user': 'aigul'}, sort_keys=True).encode())\n"
         "print(verify(forged_body + '.' + t.split('.')[1], now=900))")

