SQLI = ("import re\n\n"
        "# Оқу моделі: өте шағын «SQL» тексерушісі. Нақты дерекқор қолданбаймыз - тек тетікті көрсетеміз.\n"
        "users = [{'name': 'aigul', 'pass': 'p1', 'role': 'student'}, {'name': 'admin', 'pass': 's3cr3t', 'role': 'admin'}]\n\n"
        "def run_where(where, rows):\n"
        "    \"\"\"WHERE шартын бағалайды: name = '...' AND pass = '...' OR 1=1, -- түсініктеме\"\"\"\n"
        "    where = where.split('--')[0]                       # -- кейінгісі түсініктеме\n"
        "    out = []\n"
        "    for r in rows:\n"
        "        expr = re.sub(r\"(\\w+) = '([^']*)'\", lambda m: repr(r.get(m.group(1)) == m.group(2)), where)\n"
        "        expr = expr.replace('1=1', 'True').replace(' AND ', ' and ').replace(' OR ', ' or ')\n"
        "        if eval(expr, {'__builtins__': {}}):\n"
        "            out.append(r['name'])\n"
        "    return out\n\n"
        "def login_concat(name, pw):\n"
        "    where = f\"name = '{name}' AND pass = '{pw}'\"        # ОСАЛ: дерек кодқа айналады\n"
        "    return where, run_where(where, users)\n\n"
        "def login_param(name, pw):\n"
        "    # параметрленген: құрылым бекітілген, мәндер тек салыстырылады\n"
        "    return [r['name'] for r in users if r['name'] == name and r['pass'] == pw]\n\n"
        "for name, pw in [('aigul', 'p1'), ('aigul', 'wrong'), (\"admin' --\", 'кез келген'), (\"x' OR 1=1 --\", '')]:\n"
        "    q, res = login_concat(name, pw)\n"
        "    print(f'{name!r:16} біріктіру: {res!s:20} параметр: {login_param(name, pw)}')\n"
        "    print('    сұрау:', q)")

