XSS = ("import html\n\n"
       "comment = '<img src=x onerror=\"alert(1)\"> Сәлем & қош келдіңіз'\n\n"
       "def render_unsafe(c):\n"
       "    return f'<p class=\"comment\">{c}</p>'\n\n"
       "def render_safe(c):\n"
       "    return f'<p class=\"comment\">{html.escape(c, quote=True)}</p>'\n\n"
       "def new_tags(page, template_tags=1):\n"
       "    \"\"\"беттегі «<» арқылы ашылған тегтер саны - шаблонда біреу ғана болуы керек\"\"\"\n"
       "    return page.count('<') - page.count('</') - template_tags\n\n"
       "for name, f in [('қауіпті', render_unsafe), ('экрандалған', render_safe)]:\n"
       "    page = f(comment)\n"
       "    print(f'{name:11}: {page}')\n"
       "    print(f'{\"\":11}  қосымша тег: {new_tags(page)}')\n\n"
       "# Атрибут контексі: тырнақшаны да экрандау керек\n"
       "name = '\" onmouseover=\"alert(1)'\n"
       "print('атрибут:', f'<input value=\"{html.escape(name, quote=True)}\">')")

